CREATE OR REPLACE TEMP VIEW SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL AS SELECT CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM, COALESCE(TO_VARCHAR(ROUND(CUSTOMER_ID::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TRIM(ACCOUNT_ID), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(REPORTING_MONTH_YYYYMM::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(AVERAGE_MONTHLY_BALANCE::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_CHAR(DATE_COMPUTED, 'YYYY-MM-DD'), '\\N') AS CANONICAL_ROW, MD5(COALESCE(TO_VARCHAR(ROUND(CUSTOMER_ID::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TRIM(ACCOUNT_ID), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(REPORTING_MONTH_YYYYMM::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(AVERAGE_MONTHLY_BALANCE::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_CHAR(DATE_COMPUTED, 'YYYY-MM-DD'), '\\N')) AS ROW_HASH FROM SFNFR_20261104.SAS_AMB_LEGACY_SFNFR_20261104.MONTHLY_AMB;

CREATE OR REPLACE TEMP VIEW SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL AS SELECT CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM, COALESCE(TO_VARCHAR(ROUND(CUSTOMER_ID::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TRIM(ACCOUNT_ID), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(REPORTING_MONTH_YYYYMM::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(AVERAGE_MONTHLY_BALANCE::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_CHAR(DATE_COMPUTED, 'YYYY-MM-DD'), '\\N') AS CANONICAL_ROW, MD5(COALESCE(TO_VARCHAR(ROUND(CUSTOMER_ID::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TRIM(ACCOUNT_ID), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(REPORTING_MONTH_YYYYMM::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_VARCHAR(ROUND(AVERAGE_MONTHLY_BALANCE::NUMBER(38,6), 6)), '\\N') || '|' || COALESCE(TO_CHAR(DATE_COMPUTED, 'YYYY-MM-DD'), '\\N')) AS ROW_HASH FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.MONTHLY_AMB;

SELECT COUNT(*), HASH_AGG(CANONICAL_ROW) FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL;

SELECT COUNT(*), HASH_AGG(CANONICAL_ROW) FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL;

SELECT l.CANONICAL_ROW AS LEGACY_ROW, n.CANONICAL_ROW AS NEW_ROW FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL l FULL OUTER JOIN SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL n ON l.CUSTOMER_ID IS NOT DISTINCT FROM n.CUSTOMER_ID AND l.ACCOUNT_ID IS NOT DISTINCT FROM n.ACCOUNT_ID AND l.REPORTING_MONTH_YYYYMM IS NOT DISTINCT FROM n.REPORTING_MONTH_YYYYMM WHERE l.ROW_HASH IS DISTINCT FROM n.ROW_HASH;

SELECT COALESCE(SUM(GREATEST(a.N - COALESCE(b.N, 0), 0)), 0) FROM (SELECT CANONICAL_ROW, COUNT(*) N FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL GROUP BY CANONICAL_ROW) a LEFT JOIN (SELECT CANONICAL_ROW, COUNT(*) N FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL GROUP BY CANONICAL_ROW) b ON a.CANONICAL_ROW = b.CANONICAL_ROW;

SELECT COALESCE(SUM(GREATEST(a.N - COALESCE(b.N, 0), 0)), 0) FROM (SELECT CANONICAL_ROW, COUNT(*) N FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL GROUP BY CANONICAL_ROW) a LEFT JOIN (SELECT CANONICAL_ROW, COUNT(*) N FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL GROUP BY CANONICAL_ROW) b ON a.CANONICAL_ROW = b.CANONICAL_ROW;

SELECT COUNT(*) FROM (SELECT CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_LEGACY_CANONICAL GROUP BY CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM HAVING COUNT(*) > 1);

SELECT COUNT(*) FROM (SELECT CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM FROM SFNFR_20261104.SAS_AMB_SF_SFNFR_20261104.AMB_NEW_CANONICAL GROUP BY CUSTOMER_ID, ACCOUNT_ID, REPORTING_MONTH_YYYYMM HAVING COUNT(*) > 1);

SELECT COUNT(*) FROM SFNFR_20261104.SAS_AMB_SRC_SFNFR_20261104.CUST_ACCOUNTS;

SELECT COUNT(*) FROM SFNFR_20261104.SAS_AMB_SRC_SFNFR_20261104.DAILY_BALANCE;
